    ["sound/vo/d/m/srv_dm026.mp3"]={"speak your needs."},
    ["sound/vo/d/m/srv_dm027.mp3"]={"find someone else to bother."},
    ["sound/vo/d/m/srv_dm028.mp3"]={"i've a great selection that you'll find especially useful, outlander."},
    ["sound/vo/d/m/srv_dm029.mp3"]={"reasonable prices for top quality magic."},
    ["sound/vo/d/m/srv_dm030.mp3"]={"leave me, before you feel my dagger in your flesh!"},
    ["sound/vo/d/m/srv_dm031.mp3"]={"greetings, outlander. do you seek my services?"},
    ["sound/vo/d/m/srv_dm032.mp3"]={"my prices are reasonable."},
    ["sound/vo/d/m/srv_dm033.mp3"]={"i find you foul and disgusting. leave now."},
    ["sound/vo/d/m/srv_dm034.mp3"]={"it is a pleasure, outlander. do you require my services?"},
    ["sound/vo/d/m/srv_dm035.mp3"]={"how can i be of service to you, outlander?"},
    ["sound/vo/d/m/srv_dm036.mp3"]={"i do not wish to talk with you."},
    ["sound/vo/d/m/srv_dm037.mp3"]={"care to see the sights? where can i take you?"},
    ["sound/vo/d/m/srv_dm038.mp3"]={"short trip, long trip. you decide."},
    ["sound/vo/d/m/srv_dm039.mp3"]={"if you don't leave, i'll toss you into the drink!"},
    ["sound/vo/d/m/srv_dm040.mp3"]={"welcome, friend. what can i sell you today?"},
    ["sound/vo/d/m/srv_dm041.mp3"]={"if it is magic you are looking for, you've come to the right place!"},
    ["sound/vo/d/m/srv_dm042.mp3"]={"you are an annoyance. leave, or i shall call for the guards!"},
    ["sound/vo/d/m/srv_dm043.mp3"]={"searching for special tools? my prices are the best!"},
    ["sound/vo/d/m/srv_dm044.mp3"]={"let me relieve you of the burden of your coin."},
    ["sound/vo/d/m/srv_dm045.mp3"]={"do not waste my time."},
    ["sound/vo/d/m/srv_dm046.mp3"]={"welcome, outlander. i've special prices just for you today."},
    ["sound/vo/d/m/srv_dm047.mp3"]={"let's do some business, shall we?"},
    ["sound/vo/d/m/srv_dm048.mp3"]={"i do not conduct business with pathetic creatures like you."},
    ["sound/vo/d/m/srv_dm049.mp3"]={"care to trade?"},
    ["sound/vo/d/m/srv_dm050.mp3"]={"do you have anything to barter?"},
    ["sound/vo/d/m/srv_dm051.mp3"]={"see something you like?"},
    ["sound/vo/d/m/srv_dm052.mp3"]={"may i interest you in something?"},
    ["sound/vo/d/m/thf_dm001.mp3"]={"i'll deal with you thief!"},
    ["sound/vo/d/m/thf_dm002.mp3"]={"wretched thief!"},
    ["sound/vo/d/m/thf_dm003.mp3"]={"you're finished!"},
    ["sound/vo/d/m/thf_dm004.mp3"]={"that is quite enough thief!"},
    ["sound/vo/d/m/thf_dm005.mp3"]={"help, guards!"},
    ["sound/vo/d/m/thlo_dm001.mp3"]={"peace! now i must be silent, and join my ancestors."},
    ["sound/vo/d/m/thlo_dm002.mp3"]={"stranger! listen! i have a message i must tell you!"},
    ["sound/vo/d/m/thlo_dm003.mp3"]={"so. you're the nerevarine? well, that means nothing to me, f'lah. i don't care if you're the damn emperor."},
    ["sound/vo/d/m/thlo_dm004.mp3"]={"so. who are you? am i supposed to care? i don't care if you're the living god walking among us."},
    ["sound/vo/d/m/thlo_dm005.mp3"]={"look at this place. isn't it great?"},
    ["sound/vo/d/m/thlo_dm006.mp3"]={"with the right deal, we all profit."},
    ["sound/vo/d/m/thlo_dm007.mp3"]={"hey there, sport. what's the word?"},
    ["sound/vo/d/m/thlo_dm008.mp3"]={"well, well, well. aren't you the tasty little morsel?"},
    ["sound/vo/d/m/thlo_dm009.mp3"]={"be warned. i do not tolerate fools."},
    ["sound/vo/d/m/thlo_dm010.mp3"]={"take care, stranger."},
    ["sound/vo/d/m/thlo_dm011.mp3"]={"mind your own business."},
    ["sound/vo/d/m/thlo_dm012.mp3"]={"almalexia be praised, sera."},
    ["sound/vo/d/m/thlo_dm013.mp3"]={"hmm...you again. you wish to be of further service to our lady?"},
    ["sound/vo/d/m/thlo_dm014.mp3"]={"our city is under attack! the ordinators have been mobilized."},
    ["sound/vo/d/m/thlo_dm015.mp3"]={"the ashstorms are a nuisance, but it is as our lady wishes."},
    ["sound/vo/d/m/thlo_dm016.mp3"]={"the lady is gone...perhaps i can be of service to you?"},
    ["sound/vo/d/m/thlo_dm017.mp3"]={"grace and mercy upon you, in her name, sera."},
    ["sound/vo/d/m/thlo_dm018.mp3"]={"our lady's blessings upon you, faithful servant."},
    ["sound/vo/d/m/thlo_dm019.mp3"]={"the city is under attack? tell hler! alert the ordinators! protect the temple!"},
    ["sound/vo/d/m/thlo_dm020.mp3"]={"yes, this weather is odd, but trust in the lady. all will be well."},
    ["sound/vo/d/m/thlo_dm021.mp3"]={"what shall i do? my lady gone!"},
    ["sound/vo/d/m/thlo_dm022.mp3"]={"your loyal service shall be rewarded."},
    ["sound/vo/d/m/thlo_dm023.mp3"]={"we are in your debt, sera."},
    ["sound/vo/d/m/thlo_dm024.mp3"]={"thank you for helping us put our house in order, sera."},
    ["sound/vo/d/m/thlo_dm025.mp3"]={"captain delitian speaks well of you."},
    ["sound/vo/d/m/thlo_dm026.mp3"]={"your reputation does you honor, sera."},
    ["sound/vo/d/m/thlo_dm027.mp3"]={"we are pleased to see you, sera."},
    ["sound/vo/d/m/thlo_dm028.mp3"]={"welcome, sera."},
    ["sound/vo/d/m/thlo_dm029.mp3"]={"we are not glad to see you."},
    ["sound/vo/d/m/thlo_dm030.mp3"]={"i'm on duty. can't you see?"},
    ["sound/vo/d/m/thlo_dm031.mp3"]={"yes, i've been around, i can tell you. been there done that...."},
    ["sound/vo/d/m/thlo_dm032.mp3"]={"carry on. i'm listening."},
    ["sound/vo/d/m/thlo_dm033.mp3"]={"talk all you want. it doesn't bother me."},
    ["sound/vo/d/m/thlo_dm034.mp3"]={"me? sure. whatever."},
    ["sound/vo/d/m/thlo_dm035.mp3"]={"what are you staring at?"},
    ["sound/vo/d/m/thlo_dm036.mp3"]={"need custom armor? i'm the one you want."},
    ["sound/vo/d/m/thlo_dm037.mp3"]={"really? say your piece, churl, and be done."},
    ["sound/vo/d/m/thlo_dm038.mp3"]={"me? here? nothing. i'm doing nothing. see?"},
    ["sound/vo/d/m/thlo_dm039.mp3"]={"i'm just standing here watching. it's my job."},
    ["sound/vo/d/m/thlo_dm040.mp3"]={"pets or meat! get your scribs or rats -- finest quality!"},
    ["sound/vo/d/m/thlo_dm041.mp3"]={"look on me, and despair!"},
    ["sound/vo/d/m/thlo_dm042.mp3"]={"how nice you could stop by."},
    ["sound/vo/d/m/thlo_dm043.mp3"]={"mind your tongue, sera."},
    ["sound/vo/d/m/thlo_dm044.mp3"]={"keep a civil tongue, sera."},
    ["sound/vo/d/m/thlo_dm045.mp3"]={"i'll thank you to be brief, sera."},
    ["sound/vo/d/m/thlo_dm046.mp3"]={"you have a question."},
    ["sound/vo/d/m/thlo_dm047.mp3"]={"don't come near me!"},
    ["sound/vo/d/m/thlo_dm048.mp3"]={"welcome, comrade!"},
    ["sound/vo/d/m/thlo_dm049.mp3"]={"scram, f'lah."},
    ["sound/vo/d/m/thlo_dm050.mp3"]={"well... yes... i guess we should talk...."},
    ["sound/vo/d/m/thlo_dm051.mp3"]={"not me. oren. talk to oren."},
    ["sound/vo/d/m/thlo_dm052.mp3"]={"sorry. not interested."},
    ["sound/vo/d/m/thlo_dm053.mp3"]={"so. you're her new dog."},
    ["sound/vo/d/m/thlo_dm054.mp3"]={"i do not want company. go away."},
    ["sound/vo/d/m/thlo_dm055.mp3"]={"talk to the boss."},
    ["sound/vo/d/m/thlo_dm056.mp3"]={"i let the boss do all the talking."},
    ["sound/vo/d/m/thlo_dm057.mp3"]={"not bad for an amateur."},
    ["sound/vo/d/m/thlo_dm058.mp3"]={"could it get any worse?"},
    ["sound/vo/d/m/thlo_dm059.mp3"]={"relax. you'll be fine."},
    ["sound/vo/d/m/thlo_dm060.mp3"]={"it's never easy, is it?"},
    ["sound/vo/d/m/thlo_dm061.mp3"]={"the show is late. i wonder why."},
    ["sound/vo/d/m/thlo_dm062.mp3"]={"seles' the name, shells the game!"},
    ["sound/vo/d/m/thlo_dm063.mp3"]={"i'll thank you to be brief, sera."},
    ["sound/vo/d/m/thlo_dm064.mp3"]={"we print the truth -- the straight truth."},
    ["sound/vo/d/m/thlo_dm065.mp3"]={"talk to varis, not to me."},
    ["sound/vo/d/m/thlo_dm066.mp3"]={"talk to the boss. we just work here."},
    ["sound/vo/d/m/thlo_dm067.mp3"]={"i'm just hired help."},
    ["sound/vo/d/m/thlo_dm068.mp3"]={"this park, these plants, are hymns of praise, sera, and i'm right proud of it."},
    ["sound/vo/d/m/thlo_dm069.mp3"]={"welcome to my world, where we do things my way."},
    ["sound/vo/d/m/thlo_dm070.mp3"]={"good day, sera."},
    ["sound/vo/d/m/thlo_dm071.mp3"]={"yes? w-w-what? what do you w-w-want?"},
    ["sound/vo/d/m/thlo_dm072.mp3"]={"oh, dear. oh, m-m-my. goddess protect me."},
    ["sound/vo/d/m/thlo_dm073.mp3"]={"what is it now? must we go on?"},
    ["sound/vo/d/m/thlo_dm074.mp3"]={"justice never sleeps."},
    ["sound/vo/d/m/thlo_dm075.mp3"]={"almalexia knows and sees."},
    ["sound/vo/d/m/thlo_dm076.mp3"]={"life is a burden. bear it with honor."},
    ["sound/vo/d/m/thlo_dm077.mp3"]={"honor is food and drink for the soul."},
    ["sound/vo/d/m/thlo_dm078.mp3"]={"forget tomorrow. if you are right, act today."},
    ["sound/vo/d/m/thlo_dm079.mp3"]={"welcome to mournhold, city of the lady of mercy."},
    ["sound/vo/d/m/thlo_dm080.mp3"]={"do what is right, and all else shall follow."},
    ["sound/vo/d/m/thlo_dm081.mp3"]={"speak the truth, and all shall honor you."},
    ["sound/vo/d/m/thlo_dm082.mp3"]={"seven virtues, sera."},
    ["sound/vo/d/m/thlo_dm083.mp3"]={"show respect, sera."},
    ["sound/vo/d/m/thlo_dm084.mp3"]={"gods grant you justice, sera."},
    ["sound/vo/d/m/thlo_dm085.mp3"]={"i'll judge your words fairly, sera."},
    ["sound/vo/d/m/thlo_dm086.mp3"]={"out of our mouths, truth, sera."},
    ["sound/vo/d/m/thlo_dm087.mp3"]={"walk in mercy, sera."},
    ["sound/vo/d/m/thlo_dm088.mp3"]={"prove a friend, and earn a friend."},
    ["sound/vo/d/m/thlo_dm089.mp3"]={"a pure reputation is wealth enough for me, sera."},
    ["sound/vo/d/m/thlo_dm090.mp3"]={"be quick, and i shall serve you, sera."},
    ["sound/vo/d/m/thlo_dm091.mp3"]={"walk in her mercy, sera."},
    ["sound/vo/d/m/thlo_dm092.mp3"]={"walk in mournhold's light, sera."},
    ["sound/vo/d/m/thlo_dm093.mp3"]={"you will ask me."},
    ["sound/vo/d/m/thlo_dm094.mp3"]={"i will hear your question."},
    ["sound/vo/d/m/thlo_dm095.mp3"]={"your words shall stand witness for you, sera."},
    ["sound/vo/d/m/thlo_dm096.mp3"]={"do you have a question for me, sera?"},
    ["sound/vo/d/m/thlo_dm097.mp3"]={"respect is repaid, sera."},
    ["sound/vo/d/m/thlo_dm098.mp3"]={"your words are your measure, sera."},
    ["sound/vo/d/m/thlo_dm099.mp3"]={"blessings upon your house, sera."},
    ["sound/vo/d/m/thlo_dm100.mp3"]={"we both shall profit, sera, from your speech."},
    ["sound/vo/d/m/thlo_dm101.mp3"]={"i have ears... i shall hear."},
    ["sound/vo/d/m/thlo_dm102.mp3"]={"i trust we speak in confidence, sera?"},
    ["sound/vo/d/m/thlo_dm103.mp3"]={"may all speak well of you, sera."},
    ["sound/vo/d/m/thlo_dm104.mp3"]={"speak well of me, sera."},
    ["sound/vo/d/m/thlo_dm105.mp3"]={"do honor to our city, stranger."},
    ["sound/vo/d/m/thlo_dm106.mp3"]={"do honor to mournhold, and the lady of grace."},
    ["sound/vo/d/m/thlo_dm107.mp3"]={"almalexia's grace, and mournhold's glory."},
    ["sound/vo/d/m/thlo_dm108.mp3"]={"it is blessed to hear with patient ears."},
    ["sound/vo/d/m/thlo_dm109.mp3"]={"live in peace here, stranger."},
    ["sound/vo/d/m/thlo_dm110.mp3"]={"mournhold's peace, sera."},
    ["sound/vo/d/m/thlo_dm111.mp3"]={"let no falsehood spoil my ears, sera."},
    ["sound/vo/d/m/thlo_dm112.mp3"]={"in faith, i'm listening..."},
    ["sound/vo/d/m/thlo_dm113.mp3"]={"i'll thank you to be brief, sera."},
    ["sound/vo/d/m/thlo_dm114.mp3"]={"it's incredible. what will we do without them?"},
    ["sound/vo/d/m/thlo_dm115.mp3"]={"to arms! to arms! we're under attack!"},
    ["sound/vo/d/m/thlo_dm116.mp3"]={"gods' grief! what next?"},
    ["sound/vo/d/m/thlo_dm117.mp3"]={"i've heard talk up at the temple, and it's not good."},
    ["sound/vo/d/m/thlo_dm118.mp3"]={"from what i hear, there's trouble at the palace."},
    ["sound/vo/d/m/thlo_dm119.mp3"]={"though forbidden to some, not to you, patriarch."},
