    ["sound/vo/d/m/thlo_dm121.mp3"]={"almsivi in every hour, diviner."},
    ["sound/vo/d/m/thlo_dm122.mp3"]={"rumors flow from the house of troubles, disciple."},
    ["sound/vo/d/m/thlo_dm123.mp3"]={"comfort is given, justice is taken, curate."},
    ["sound/vo/d/m/thlo_dm124.mp3"]={"count only the happy hours, adept."},
