    ["sound/vo/d/m/thlo_dm126.mp3"]={"three blessings, initiate."},
    ["sound/vo/d/m/thlo_dm127.mp3"]={"almsivi grant you humility, novice."},
    ["sound/vo/d/m/thlo_dm128.mp3"]={"learn by serving, layman."},
