    ["sound/vo/d/m/thlo_dm178.mp3"]={"how do you like mournhold, imperial?"},
    ["sound/vo/d/m/thlo_dm179.mp3"]={"i'm not busy now. what do you need?"},
    ["sound/vo/d/m/thlo_dm180.mp3"]={"time to talk? i've a few minutes...."},
    ["sound/vo/d/m/thlo_dm181.mp3"]={"happy to help. what's your problem?"},
    ["sound/vo/d/m/thlo_dm182.mp3"]={"oh... it's you. can i help you?"},
    ["sound/vo/d/m/thlo_dm183.mp3"]={"whatever you want... within reason."},
    ["sound/vo/d/m/thlo_dm184.mp3"]={"if a few words can help, i'd be happy to talk."},
    ["sound/vo/d/m/thlo_dm185.mp3"]={"yes?"},
    ["sound/vo/d/m/thlo_dm186.mp3"]={"mournhold! city of light! city of magic!"},
    ["sound/vo/d/m/thlo_dm187.mp3"]={"it's fine with me. go ahead."},
    ["sound/vo/d/m/thlo_dm188.mp3"]={"go ahead. i'm waiting."},
    ["sound/vo/d/m/thlo_dm189.mp3"]={"excuse me. did you say something?"},
    ["sound/vo/d/m/thlo_dm190.mp3"]={"excuse me. i was just thinking..."},
    ["sound/vo/d/m/thlo_dm191.mp3"]={"how are you today?"},
    ["sound/vo/d/m/thlo_dm192.mp3"]={"i'm listening."},
    ["sound/vo/d/m/thlo_dm193.mp3"]={"what is it now?"},
    ["sound/vo/d/m/thlo_dm194.mp3"]={"talk if you're talking."},
    ["sound/vo/d/m/thlo_dm195.mp3"]={"will this take long?"},
    ["sound/vo/d/m/thlo_dm196.mp3"]={"talk is cheap."},
    ["sound/vo/d/m/thlo_dm197.mp3"]={"well?"},
    ["sound/vo/d/m/thlo_dm198.mp3"]={"so? you want something?"},
    ["sound/vo/d/m/thlo_dm199.mp3"]={"go on. i can't stop you."},
    ["sound/vo/d/m/thlo_dm200.mp3"]={"if you insist..."},
    ["sound/vo/d/m/tidl_dm001.mp3"]={"the lords' will be done. see to it."},
    ["sound/vo/d/m/tidl_dm002.mp3"]={"try me, and you'll regret it."},
