    ["sound/vo/i/m/bhlo_im005.mp3"]={"yes? what can i do for you? i am captain falx carius, commander of fort frostmoth."},
    ["sound/vo/i/m/bhlo_im006.mp3"]={"stuck here. forever. i'll die."},
