    ["sound/vo/n/m/bhlo_nm040.mp3"]={"you've returned from the lake! i trust you completed your task."},
    ["sound/vo/n/m/bhlo_nm041.mp3"]={"you are to prove your strength as a warrior of the skaal."},
    ["sound/vo/n/m/bhlo_nm042.mp3"]={"you have done well, showing your loyalty and wisdom"},
    ["sound/vo/n/m/bhlo_nm043.mp3"]={"you were to investigate a crime. have you done this?"},
    ["sound/vo/n/m/bhlo_nm044.mp3"]={"you have shown your loyalty to the skaal."},
    ["sound/vo/n/m/bhlo_nm045.mp3"]={"you were told to perform the rituals needed to restore the power of the skaal. what have you done?"},
    ["sound/vo/n/m/bhlo_nm046.mp3"]={"i was trying to explain to you, outlander, that you have much to atone for."},
    ["sound/vo/n/m/bhlo_nm047.mp3"]={"you've returned to our village, outlander. what is your business here?"},
    ["sound/vo/n/m/bhlo_nm048.mp3"]={"there is no more to say to you, stranger. the skaal wish you no harm, but you are not welcome here."},
    ["sound/vo/n/m/bhlo_nm049.mp3"]={"what do you want, stranger? why are you among the skaal?"},
    ["sound/vo/n/m/bhlo_nm050.mp3"]={"what can long-tooth do for you?"},
    ["sound/vo/n/m/bhlo_nm051.mp3"]={"the spirit bear is dead, and the ristaag is nearly complete."},
    ["sound/vo/n/m/bhlo_nm052.mp3"]={"you and i must continue the ristaag."},
    ["sound/vo/n/m/bhlo_nm053.mp3"]={"shhh...we must hunt carefully and quietly. there is no time to talk."},
    ["sound/vo/n/m/bhlo_nm054.mp3"]={"come back at nightfall, my friend. we will perform the ristaag."},
    ["sound/vo/n/m/bhlo_nm055.mp3"]={"greetings, blodskaal. korst wind-eye has told me much about you."},
    ["sound/vo/n/m/bhlo_nm056.mp3"]={"we must complete the ristaag. the all-maker demands this."},
    ["sound/vo/n/m/bhlo_nm057.mp3"]={"you have cleared my name and restored my honor. what can i do for you, my friend?"},
    ["sound/vo/n/m/bhlo_nm058.mp3"]={"you, who are to be my judge, what would you ask of me?"},
    ["sound/vo/n/m/bhlo_nm059.mp3"]={"have you come for stalhrim armor, friend?"},
    ["sound/vo/n/m/bhlo_nm060.mp3"]={"speak to graring."},
    ["sound/vo/n/m/bhlo_nm061.mp3"]={"begone, stranger."},
    ["sound/vo/n/m/bhlo_nm062.mp3"]={"what is it, friend?"},
    ["sound/vo/n/m/bhlo_nm063.mp3"]={"we'll have no dealings with the likes of you. begone."},
    ["sound/vo/n/m/bhlo_nm064.mp3"]={"you'll not infect me with your devilry! i am here to defend nature, and i'll do so at any cost! now begone!"},
    ["sound/vo/n/m/bhlo_nm065.mp3"]={"look, i said i'll leave. just stay away from me, will you?"},
    ["sound/vo/n/m/bhlo_nm066.mp3"]={"let's get a move on."},
    ["sound/vo/n/m/bhlo_nm067.mp3"]={"be careful out here in the wild, friend. there's more roaming about than just wolves and bears."},
    ["sound/vo/n/m/bhlo_nm068.mp3"]={"\\in the cave he met the beast"},
    ["sound/vo/n/m/bhlo_nm068a.mp3"]={"\\in the cave she met the beast"},
    ["sound/vo/n/m/bhlo_nm069.mp3"]={"werewolves in the greathall! get in there quickly!"},
    ["sound/vo/n/m/bhlo_nm070.mp3"]={"quickly, into the greathall! some of the beasts ran inside!"},
    ["sound/vo/n/m/bhlo_nm071.mp3"]={"let us fight through to the end."},
    ["sound/vo/n/m/bhlo_nm072.mp3"]={"no time for talk. the hunt has begun!"},
    ["sound/vo/n/m/bhlo_nm073.mp3"]={"you have returned. i would hear of your journey."},
    ["sound/vo/n/m/bhlo_nm074.mp3"]={"the skaal will endure."},
    ["sound/vo/n/m/bhlo_nm075.mp3"]={"it is an honor, blodskaal."},
    ["sound/vo/n/m/bidl_nm001.mp3"]={"cold enough for ya, eh?"},
    ["sound/vo/n/m/bidl_nm002.mp3"]={"my teeth itch."},
    ["sound/vo/n/m/bidl_nm003.mp3"]={"you're a long way from civilization, pilgrim."},
    ["sound/vo/n/m/bidl_nm004.mp3"]={"ah... ah... ah... choooo!"},
    ["sound/vo/n/m/bidl_nm005.mp3"]={"so, this tooth-paste-stuff... what's it for? fixing old teeth?"},
    ["sound/vo/n/m/bidl_nm006.mp3"]={"just rub a little bear grease on it -- be good as new."},
    ["sound/vo/n/m/bidl_nm007.mp3"]={"he said it was fresh, but i don't know. it looked kinda like dog to me."},
    ["sound/vo/n/m/bidl_nm008.mp3"]={"no, don't eat the skin, for gods sake. you don't know where it's been."},
    ["sound/vo/n/m/bidl_nm010.mp3"]={"some people are born dumb. like me, for instance."},
    ["sound/vo/n/m/bidl_nm011.mp3"]={"it was a rock. who cares what kind of rock."},
    ["sound/vo/n/m/bidl_nm012.mp3"]={"all this, and in the spring, mud and flies, too."},
    ["sound/vo/n/m/bidl_nm013.mp3"]={"well, at least being cold, wet, and miserable all the time gives us plenty to complain about."},
    ["sound/vo/n/m/bidl_nm014.mp3"]={"*pfbbbbbbbt*"},
    ["sound/vo/n/m/bidl_nm015.mp3"]={"oh, not again!"},
    ["sound/vo/n/m/bidl_nm016.mp3"]={"[wide yawn.]"},
    ["sound/vo/n/m/bidl_nm017.mp3"]={"stranger and guest..."},
    ["sound/vo/n/m/bidl_nm018.mp3"]={"no guest of the skaal shall want for hospitality."},
    ["sound/vo/n/m/bidl_nm019.mp3"]={"strange times, and stranger..."},
    ["sound/vo/n/m/bidl_nm020.mp3"]={"strange signs, carried on the wind..."},
    ["sound/vo/n/m/bidl_nm021.mp3"]={"uh-huh."},
    ["sound/vo/n/m/bidl_nm022.mp3"]={"right."},
    ["sound/vo/n/m/bidl_nm023.mp3"]={"no point worrying about it."},
    ["sound/vo/n/m/bidl_nm024.mp3"]={"just as well..."},
    ["sound/vo/n/m/bidl_nm025.mp3"]={"could be worse. probably will be."},
    ["sound/vo/n/m/bidl_nm026.mp3"]={"wonder what he's up to."},
    ["sound/vo/n/m/bidl_nm027.mp3"]={"wonder what she's up to."},
    ["sound/vo/n/m/bidl_nm028.mp3"]={"what a life."},
    ["sound/vo/n/m/bidl_nm029.mp3"]={"it's a hard life, but it's fair."},
    ["sound/vo/n/m/bidl_nm030.mp3"]={"oh, brother... not again...."},
    ["sound/vo/n/m/bidl_nm031.mp3"]={"i'm still in pretty good shape... right?"},
    ["sound/vo/n/m/bidl_nm032.mp3"]={"i took care of it... didn't i?"},
    ["sound/vo/n/m/bidl_nm033.mp3"]={"look, don't tell me about your problems...."},
    ["sound/vo/n/m/bidl_nm034.mp3"]={"there is great power in this place."},
    ["sound/vo/n/m/bidl_nm035.mp3"]={"heart-fang shall survive the hunt."},
    ["sound/vo/n/m/bidl_nm036.mp3"]={"the bloodmoon is in the sky. who knows what will befall us."},
    ["sound/vo/n/m/bidl_nm037.mp3"]={"the signs have faded. the prophecy is at an end."},
