    ["sound/vo/w/m/atk_wm009.mp3"]={"one of us will die here and it won't be me."},
    ["sound/vo/w/m/atk_wm010.mp3"]={"this is too easy."},
    ["sound/vo/w/m/atk_wm011.mp3"]={"fight coward!"},
    ["sound/vo/w/m/atk_wm012.mp3"]={"you should run now."},
    ["sound/vo/w/m/atk_wm013.mp3"]={"i'll see you dead."},
    ["sound/vo/w/m/atk_wm018.mp3"]={"no one can challenge me!"},
    ["sound/vo/w/m/fle_wm001.mp3"]={"there will be vengeance! this is not the last of this!"},
    ["sound/vo/w/m/fle_wm002.mp3"]={"when we meet again, you will die!"},
    ["sound/vo/w/m/fle_wm003.mp3"]={"get away! i do not wish to fight!"},
    ["sound/vo/w/m/fle_wm004.mp3"]={"i will deny you your victory and the spoils!"},
    ["sound/vo/w/m/fle_wm005.mp3"]={"aaaagh!"},
    ["sound/vo/w/m/flw_wm002.mp3"]={"careful with that, friend!"},
    ["sound/vo/w/m/hit_wm001.mp3"]={"arrgh."},
    ["sound/vo/w/m/hit_wm002.mp3"]={"eeek"},
    ["sound/vo/w/m/hit_wm003.mp3"]={"oooff."},
    ["sound/vo/w/m/hit_wm004.mp3"]={"ughn","ungh!"},
    ["sound/vo/w/m/hit_wm005.mp3"]={"stoopid."},
    ["sound/vo/w/m/hit_wm006.mp3"]={"aiieee."},
    ["sound/vo/w/m/hit_wm007.mp3"]={"groan."},
    ["sound/vo/w/m/hit_wm008.mp3"]={"groan."},
    ["sound/vo/w/m/hit_wm009.mp3"]={"groan."},
    ["sound/vo/w/m/hit_wm010.mp3"]={"grunt."},
    ["sound/vo/w/m/hit_wm011.mp3"]={"grunt.","umph!"},
    ["sound/vo/w/m/hit_wm012.mp3"]={"groan.","ooomph!"},
    ["sound/vo/w/m/hit_wm013.mp3"]={"growl."},
    ["sound/vo/w/m/hit_wm014.mp3"]={"gasp."},
    ["sound/vo/w/m/hit_wm015.mp3"]={"scream."},
    ["sound/vo/w/m/hlo_wm001.mp3"]={"go back where you came from."},
    ["sound/vo/w/m/hlo_wm002.mp3"]={"not now, redguard."},
    ["sound/vo/w/m/hlo_wm003.mp3"]={"not now, orc."},
    ["sound/vo/w/m/hlo_wm004.mp3"]={"not now, nord."},
    ["sound/vo/w/m/hlo_wm005.mp3"]={"not now, khajiit."},
    ["sound/vo/w/m/hlo_wm006.mp3"]={"not now, cyrodil."},
    ["sound/vo/w/m/hlo_wm007.mp3"]={"not now, altmer."},
    ["sound/vo/w/m/hlo_wm008.mp3"]={"not now, dunmer."},
    ["sound/vo/w/m/hlo_wm009.mp3"]={"not now, breton."},
    ["sound/vo/w/m/hlo_wm010.mp3"]={"not now, argonian."},
    ["sound/vo/w/m/hlo_wm011.mp3"]={"i take comfort in knowing you're not long for this world."},
    ["sound/vo/w/m/hlo_wm012.mp3"]={"your wounds are disgusting. go away."},
    ["sound/vo/w/m/hlo_wm013.mp3"]={"ugh, why don't you just die already?"},
    ["sound/vo/w/m/hlo_wm014.mp3"]={"if you're here to beg for coins, go away."},
    ["sound/vo/w/m/hlo_wm015.mp3"]={"interesting outfit. you might get caught dead in it."},
    ["sound/vo/w/m/hlo_wm016.mp3"]={"dressed yourself, i see."},
    ["sound/vo/w/m/hlo_wm017.mp3"]={"if there's an excuse to wear clothes, you're it."},
    ["sound/vo/w/m/hlo_wm018.mp3"]={"avoid the guards, thief, and you might live til tommorrow."},
    ["sound/vo/w/m/hlo_wm019.mp3"]={"you're a disgrace."},
    ["sound/vo/w/m/hlo_wm020.mp3"]={"take your infections somewhere else."},
    ["sound/vo/w/m/hlo_wm021.mp3"]={"why must you people always pick on the small ones? go away."},
    ["sound/vo/w/m/hlo_wm022.mp3"]={"can't you see i wish to be left alone!"},
    ["sound/vo/w/m/hlo_wm023.mp3"]={"useless tourists."},
    ["sound/vo/w/m/hlo_wm024.mp3"]={"you'll get more than you bargained for from me!","you'll get more than you bargained for from me."},
    ["sound/vo/w/m/hlo_wm025.mp3"]={"i really don't want you around here."},
    ["sound/vo/w/m/hlo_wm026.mp3"]={"don't bother me."},
    ["sound/vo/w/m/hlo_wm027.mp3"]={"can't you find someone else to bother?"},
    ["sound/vo/w/m/hlo_wm028.mp3"]={"i don't like you much."},
    ["sound/vo/w/m/hlo_wm029.mp3"]={"isn't there someone else you can talk to?"},
    ["sound/vo/w/m/hlo_wm030.mp3"]={"i'm sorry, you probably want to speak with someone else."},
    ["sound/vo/w/m/hlo_wm031.mp3"]={"this better be important, redguard."},
    ["sound/vo/w/m/hlo_wm032.mp3"]={"this better be important, orc."},
    ["sound/vo/w/m/hlo_wm033.mp3"]={"this better be important, nord."},
    ["sound/vo/w/m/hlo_wm034.mp3"]={"this better be important, khajiit."},
    ["sound/vo/w/m/hlo_wm035.mp3"]={"this better be important, cyrodil."},
    ["sound/vo/w/m/hlo_wm036.mp3"]={"this better be important, altmer."},
    ["sound/vo/w/m/hlo_wm037.mp3"]={"this better be important, dunmer."},
    ["sound/vo/w/m/hlo_wm038.mp3"]={"this better be important, breton."},
    ["sound/vo/w/m/hlo_wm039.mp3"]={"this better be important, argonian."},
    ["sound/vo/w/m/hlo_wm040.mp3"]={"is it really necessary that we talk?"},
    ["sound/vo/w/m/hlo_wm041.mp3"]={"why aren't you working?"},
    ["sound/vo/w/m/hlo_wm042.mp3"]={"shouldn't you be at your post?"},
    ["sound/vo/w/m/hlo_wm043.mp3"]={"you could at least try and be civilized and dress appropriately."},
    ["sound/vo/w/m/hlo_wm044.mp3"]={"let me guess. you were robbed and dressed in those ridiculous clothes."},
    ["sound/vo/w/m/hlo_wm045.mp3"]={"if your clothes are any indictation, i take it you're a herder."},
    ["sound/vo/w/m/hlo_wm046.mp3"]={"the laws are harsh for thieves. including yourself."},
    ["sound/vo/w/m/hlo_wm047.mp3"]={"i don't think you can be trusted."},
    ["sound/vo/w/m/hlo_wm048.mp3"]={"you're wounded, but you'll live. now move on."},
    ["sound/vo/w/m/hlo_wm049.mp3"]={"if you're strong enough to walk, you should find healing."},
    ["sound/vo/w/m/hlo_wm050.mp3"]={"there's healing elsewhere. go find it."},
    ["sound/vo/w/m/hlo_wm051.mp3"]={"i'm not impressed. find yourself some rags."},
    ["sound/vo/w/m/hlo_wm052.mp3"]={"oh, that's some infection you have there."},
    ["sound/vo/w/m/hlo_wm053.mp3"]={"i couldn't possibly. too busy."},
    ["sound/vo/w/m/hlo_wm054.mp3"]={"i'm sure this is important, but i really must go."},
    ["sound/vo/w/m/hlo_wm055.mp3"]={"too much trouble. must be going now."},
    ["sound/vo/w/m/hlo_wm056.mp3"]={"i really can't help you, stranger."},
    ["sound/vo/w/m/hlo_wm057.mp3"]={"this better be important."},
    ["sound/vo/w/m/hlo_wm058.mp3"]={"i really don't have time for this, so make it quick."},
    ["sound/vo/w/m/hlo_wm059.mp3"]={"hurry this up, will you?"},
    ["sound/vo/w/m/hlo_wm060.mp3"]={"sorry, stranger, my time is short, so get on with it."},
    ["sound/vo/w/m/hlo_wm061.mp3"]={"if i can help i will, but don't take too much time."},
    ["sound/vo/w/m/hlo_wm062.mp3"]={"go ahead."},
    ["sound/vo/w/m/hlo_wm063.mp3"]={"out with it, woman!"},
    ["sound/vo/w/m/hlo_wm064.mp3"]={"what is this about, redguard?"},
    ["sound/vo/w/m/hlo_wm065.mp3"]={"what is this about, orc?"},
    ["sound/vo/w/m/hlo_wm066.mp3"]={"what is this about, nord?"},
    ["sound/vo/w/m/hlo_wm067.mp3"]={"what is this about, khajiit?"},
    ["sound/vo/w/m/hlo_wm068.mp3"]={"what is this about, cyrodil?"},
    ["sound/vo/w/m/hlo_wm069.mp3"]={"what is this about, altmer?"},
    ["sound/vo/w/m/hlo_wm070.mp3"]={"what is this about, dunmer?"},
    ["sound/vo/w/m/hlo_wm071.mp3"]={"what is this about, breton?"},
    ["sound/vo/w/m/hlo_wm072.mp3"]={"what is this about, argonian?"},
    ["sound/vo/w/m/hlo_wm073.mp3"]={"you shouldn't be out in this mess."},
    ["sound/vo/w/m/hlo_wm074.mp3"]={"how do you travel in this?"},
    ["sound/vo/w/m/hlo_wm075.mp3"]={"rain again."},
    ["sound/vo/w/m/hlo_wm076.mp3"]={"nice day, don't you think?"},
    ["sound/vo/w/m/hlo_wm077.mp3"]={"go ahead."},
    ["sound/vo/w/m/hlo_wm078.mp3"]={"well, what is this about?"},
    ["sound/vo/w/m/hlo_wm079.mp3"]={"are you here about your wounds? you should find healing."},
    ["sound/vo/w/m/hlo_wm080.mp3"]={"someone has taken their toll on you. maybe you should get healed."},
    ["sound/vo/w/m/hlo_wm081.mp3"]={"what happened to you? you're nearly dead."},
    ["sound/vo/w/m/hlo_wm082.mp3"]={"from where do you hail?"},
    ["sound/vo/w/m/hlo_wm083.mp3"]={"what is this about?"},
    ["sound/vo/w/m/hlo_wm084.mp3"]={"all right, i'm listening."},
    ["sound/vo/w/m/hlo_wm085.mp3"]={"hello. i don't know if i can help you, but i'll try."},
    ["sound/vo/w/m/hlo_wm086.mp3"]={"do you want something from me?"},
    ["sound/vo/w/m/hlo_wm087.mp3"]={"how may i help you?"},
    ["sound/vo/w/m/hlo_wm088.mp3"]={"i'm listening."},
    ["sound/vo/w/m/hlo_wm089.mp3"]={"interesting, go on."},
    ["sound/vo/w/m/hlo_wm090.mp3"]={"how do you do?"},
    ["sound/vo/w/m/hlo_wm091.mp3"]={"what can i do for you?"},
    ["sound/vo/w/m/hlo_wm092.mp3"]={"i've rarely seen one as lovely as you. please, ask your question."},
    ["sound/vo/w/m/hlo_wm093.mp3"]={"how do you do, redguard?"},
    ["sound/vo/w/m/hlo_wm094.mp3"]={"how do you do, orc?"},
    ["sound/vo/w/m/hlo_wm095.mp3"]={"how do you do, nord?"},
    ["sound/vo/w/m/hlo_wm096.mp3"]={"how do you do, khajiit?"},
    ["sound/vo/w/m/hlo_wm097.mp3"]={"how do you do, cyrodil?"},
    ["sound/vo/w/m/hlo_wm098.mp3"]={"how do you do, altmer?"},
    ["sound/vo/w/m/hlo_wm099.mp3"]={"how do you do, dunmer?"},
    ["sound/vo/w/m/hlo_wm100.mp3"]={"how do you do, breton?"},
    ["sound/vo/w/m/hlo_wm101.mp3"]={"how do you do, argonian?"},
    ["sound/vo/w/m/hlo_wm102.mp3"]={"have you run into trouble? you seem wounded."},
    ["sound/vo/w/m/hlo_wm103.mp3"]={"something must have gotten hold of you. you're half-dead."},
    ["sound/vo/w/m/hlo_wm104.mp3"]={"those are some serious wounds. you should find healing quick."},
    ["sound/vo/w/m/hlo_wm105.mp3"]={"i've heard of your crimes. maybe you should talk to someone else."},
    ["sound/vo/w/m/hlo_wm106.mp3"]={"criminals should dealt with harshly, don't you think?"},
    ["sound/vo/w/m/hlo_wm107.mp3"]={"you're infected. go find a healer."},
    ["sound/vo/w/m/hlo_wm108.mp3"]={"yes?"},
    ["sound/vo/w/m/hlo_wm109.mp3"]={"of course. what may i do for you?"},
    ["sound/vo/w/m/hlo_wm110.mp3"]={"yes, stranger?"},
    ["sound/vo/w/m/hlo_wm111.mp3"]={"and how are you? can i help you?"},
    ["sound/vo/w/m/hlo_wm112.mp3"]={"hello."},
    ["sound/vo/w/m/hlo_wm113.mp3"]={"how are you?"},
    ["sound/vo/w/m/hlo_wm114.mp3"]={"three blessings, friend."},
    ["sound/vo/w/m/hlo_wm115.mp3"]={"how can i help? i'll do what i can."},
    ["sound/vo/w/m/hlo_wm116.mp3"]={"how nice, i like good company. what can i do for you?"},
    ["sound/vo/w/m/hlo_wm117.mp3"]={"i am honored to meet you."},
    ["sound/vo/w/m/hlo_wm118.mp3"]={"i think you're a thief, because you've stolen my heart."},
    ["sound/vo/w/m/hlo_wm119.mp3"]={"to what do i owe the honor, redguard?"},
    ["sound/vo/w/m/hlo_wm120.mp3"]={"to what do i owe the honor, orc?"},
    ["sound/vo/w/m/hlo_wm121.mp3"]={"to what do i owe the honor, nord?"},
    ["sound/vo/w/m/hlo_wm122.mp3"]={"to what do i owe the honor, khajiit?"},
    ["sound/vo/w/m/hlo_wm123.mp3"]={"to what do i owe the honor, cyrodil?"},
    ["sound/vo/w/m/hlo_wm124.mp3"]={"to what do i owe the honor, altmer?"},
    ["sound/vo/w/m/hlo_wm125.mp3"]={"to what do i owe the honor, dunmer?"},
    ["sound/vo/w/m/hlo_wm126.mp3"]={"to what do i owe the honor, breton?"},
    ["sound/vo/w/m/hlo_wm127.mp3"]={"to what do i owe the honor, argonian?"},
    ["sound/vo/w/m/hlo_wm128.mp3"]={"are you all right? you look wounded."},
    ["sound/vo/w/m/hlo_wm129.mp3"]={"oh, dear, what happened? you're half-dead."},
    ["sound/vo/w/m/hlo_wm131.mp3"]={"this is a rare honor."},
    ["sound/vo/w/m/hlo_wm132.mp3"]={"hail, friend."},
    ["sound/vo/w/m/hlo_wm133.mp3"]={"how free you are, to venture in the nude!"},
    ["sound/vo/w/m/hlo_wm134.mp3"]={"greetings and salutations."},
    ["sound/vo/w/m/hlo_wm135.mp3"]={"i have a feeling that you and i are about to become very close."},
    ["sound/vo/w/m/hlo_wm136.mp3"]={"this is a wondrous encounter. welcome."},
    ["sound/vo/w/m/hlo_wm137.mp3"]={"if there is anything i can do, i am humbly at your service."},
    ["sound/vo/w/m/hlo_wm138.mp3"]={"you don't want to kill me do you?"},
    ["sound/vo/w/m/idl_wm001.mp3"]={"sniff."},
    ["sound/vo/w/m/idl_wm002.mp3"]={"cough."},
    ["sound/vo/w/m/idl_wm003.mp3"]={"sigh."},
    ["sound/vo/w/m/idl_wm004.mp3"]={"whistle."},
    ["sound/vo/w/m/idl_wm005.mp3"]={"humm."},
    ["sound/vo/w/m/idl_wm006.mp3"]={"sigh."},
    ["sound/vo/w/m/idl_wm007.mp3"]={"grumbles."},
    ["sound/vo/w/m/idl_wm008.mp3"]={"sigh."},
    ["sound/vo/w/m/idl_wm009.mp3"]={"that's unusual."},
    ["sound/vo/w/m/thf_wm001.mp3"]={"no! stop!"},
    ["sound/vo/w/m/thf_wm002.mp3"]={"outrageous!"},
    ["sound/vo/w/m/thf_wm003.mp3"]={"over here!"},
    ["sound/vo/w/m/thf_wm004.mp3"]={"you've stolen for the last time, thief!"},
    ["sound/vo/w/m/thf_wm005.mp3"]={"what's this? thief!"},
  },
  scripts={
    ["sound/vo/a/m/flw_am001.mp3"]="Where are you going?",
    ["sound/vo/a/m/flw_am003.mp3"]="Thank you.",
    ["sound/vo/b/f/flw_bf004.mp3"]="Hey! Wait for me!",
    ["sound/vo/d/f/flw_df003.mp3"]="Thank you.",
    ["sound/vo/d/f/flw_df004.mp3"]="Hey! Wait for me!",
    ["sound/vo/d/m/flw_dm001.mp3"]="Where are you going?",
    ["sound/vo/d/m/flw_dm003.mp3"]="Thank you.",
    ["sound/vo/d/m/flw_dm004.mp3"]="Thank you.",
    ["sound/vo/f/m/flw_hf003.mp3"]="Thank you.",
    ["sound/vo/h/f/flw_hf003.mp3"]="Thank you.",
    ["sound/vo/h/f/flw_hf004.mp3"]="Hey! Wait for me!",
    ["sound/vo/h/m/flw_hm003.mp3"]="Thank you.",
    ["sound/vo/h/m/flw_hm004.mp3"]="Hey! Wait for me!",
    ["sound/vo/i/m/flw_im001.mp3"]="Where are you going?",
    ["sound/vo/i/m/flw_im003.mp3"]="Thank you.",
    ["sound/vo/k/m/flw_km003.mp3"]="Many thanks.",
    ["sound/vo/misc/a2-6_cave_closed.mp3"]="The door is locked, and will not open. The star is the key.",
    ["sound/vo/misc/a2-6_cave_open.mp3"]="In the dawn hour under Azura's Star, the door is opened.",
    ["sound/vo/misc/bill_assantus.wav"]="Assantus: 'Thank you, Outlander. You are a kind and generous soul.'",
    ["sound/vo/misc/bill_diedog.wav"]="Die like a dog.",
    ["sound/vo/misc/bill_fg_nchurdamz01.wav"]="Hrelvsuu! I have come for you! Show yourself!",
    ["sound/vo/misc/bill_fg_nchurdamz02.wav"]="I can smell the stench of the Daedroth. It is here and I will find it!'",
    ["sound/vo/misc/bill_fg_nchurdamz03.wav"]="The beast is near now ... very near. Be on your guard.'",
    ["sound/vo/misc/bill_fg_nchurdamz04.wav"]="Larienna: 'At last! A means to vanquish Hrelvesuu. The final battle awaits!'",
    ["sound/vo/misc/bill_lariennaend.wav"]="Larienna: 'Hrelvesuu is vanquished, yet somehow I feel uneasy. I must investigate these ruins further. You have been a worthy companion. Farewell my friend.'",
    ["sound/vo/misc/bill_nogooddeed.wav"]="No good deed goes unpunished, Outlander.",
    ["sound/vo/misc/bm_wildhunt1.wav"]="Ahhh...you have arrived. The others have been here for days now, and you are the last. It is time for my Hunt, and you are to take part. I have chosen only the most worthy to take part the Hunt--Carius of the Imperials, Heart-Fang of the Skaal, the frost giant Karstaag....and you. You have proven yourself a worthy hunter, and so you have been given this honor.",
    ["sound/vo/misc/bm_wildhunt2.wav"]="You and the others are to find your way to my Hunting Grounds. Take great care, as only one of you will earn the glory of facing the Hunter himself in battle while the Bloodmoon lights the sky. The others have gone ahead, so only you remain to begin. Beware, mortal--my Hounds are about, and they hunger for blood. Perhaps I will see you soon. Now go.",
    ["sound/vo/misc/bm_wildhunt3.wav"]="So...you are the one. You have escaped my hounds and beaten back the other challengers. I had rather expected the giant to prevail, but no matter. You have proven yourself a worthy hunter, and you have earned the greatest honor that can be bestowed upon a mortal: you are to be my prey.",
    ["sound/vo/misc/bm_wildhunt4.wav"]="I ask you, though: what is it that makes a hunter great. Is it his strength? The speed with which he strikes? Or is it his guile, the ability to outwit his prey? Answer me, mortal, and decide your fate.",
    ["sound/vo/misc/bm_wildhunt5.wav"]="So you have chosen, and so shall be your fate. To face me in all my glory would be less than sporting, so you shall face but one of my aspects, the one you have chosen. We have little time--the Bloodmoon sinks low in the sky. Prepare yourself, mortal, for now you are the Hunted.",
    ["sound/vo/misc/chargen birth.wav"]="Very good. The letter that preceded you mentioned you were born under a certain sign. And what would that be?",
    ["sound/vo/misc/chargen class1.wav"]="Ahh yes, we've been expecting you. You'll have to be recorded before you're officially released. There are a few ways we can do this, and the choice is yours.",
    ["sound/vo/misc/chargen class2.wav"]="Interesting. Now before I stamp these papers, make sure this information is correct.",
    ["sound/vo/misc/chargen class3.wav"]="Show your papers to the Captain when you exit to get your release fee.",
    ["sound/vo/misc/chargen class4.wav"]="Take your papers off the table and go see Captain Gravius.",
    ["sound/vo/misc/chargen door1.wav"]="You'll go no further until you have your papers.",
    ["sound/vo/misc/chargen door2.wav"]="Continue through to the next building, and talk to Sellus Gravius.",
    ["sound/vo/misc/chargenboat1.wav"]="This is where they want you. Head down to the dock and he'll show you to the Census Office.",
    ["sound/vo/misc/chargenboat2.wav"]="Let's go. Move it along.",
    ["sound/vo/misc/chargendock1.wav"]="You finally arrived, but our records don't show from where.",
    ["sound/vo/misc/chargendock2.wav"]="Great. I'm sure you'll fit right in. Follow me up to the office and they'll finish your release.",
    ["sound/vo/misc/chargendock3.wav"]="Head on in.",
    ["sound/vo/misc/chargenname1.wav"]="Stand up, there you go. You were dreaming. What's your name?",
    ["sound/vo/misc/chargenname2.wav"]="Well, not even last night's storm could wake you. I heard them say we've reached Morrowind. I'm sure they'll let us go.",
    ["sound/vo/misc/chargenname3.wav"]="Quiet, here comes the guard.",
    ["sound/vo/misc/chargenname4.wav"]="You better do what they say.",
    ["sound/vo/misc/chargenwalk1.wav"]="This is where you get off, come with me.",
    ["sound/vo/misc/chargenwalk2.wav"]="Get yourself up on deck, and let's keep this as civil as possible.",
    ["sound/vo/misc/chargenwalk3.wav"]="On deck now, prisoner.",
    ["sound/vo/misc/chargenwoman1.wav"]="The sooner you leave, the sooner we can move on.",
    ["sound/vo/misc/chargenwoman2.wav"]="Yes, confused? We're all waiting.",
    ["sound/vo/misc/da_azuracomplete.wav"]="Well done, mortal. You have preserved the integrity of my wager with Sheogorath. Now it will end as fated, and not due to the meddling of the Daedra Prince. Take this, and use it wisely.",
    ["sound/vo/misc/da_azurafail.wav"]="You have caused me to lose my wager, mortal. Now, it matters not that Sheogorath meddled in the outcome of our wager. You have failed, but it seems that is your fate.",
    ["sound/vo/misc/da_azuraintro1.wav"]="You have come here for a reason, though you may not know what it is. Sheogorath and I have made a wager. He contends that solitude causes madness, while I maintain it allows for solace and meditation. To test this, I sent one of my priestesses to live alone on an island north of Dagon Fel. If she can live there for 100 years, continuing her life of prayer, my theory will be proven. If not, Sheogorath wins our wager.",
    ["sound/vo/misc/da_azuraintro2.wav"]="The time has almost passed, and she remains steadfast. But, Sheogorath has tried to sway the decision in his favor. Travel there, rid the island of his minions, and bring back proof of his meddling. Do not disturb the wise woman, though, as that would void our wager. Serve me, and I will reward you well.",
    ["sound/vo/misc/da_boethiahcomplete.wav"]="You have done well. This shrine is a worthy one, and my power will again be felt. Take this, mortal. Wield the Goldbrand with a strong hand, and let all know that my Shrine has risen!",
    ["sound/vo/misc/da_boethiahintro1.wav"]="What do you want with me, mortal? My shrine is in ruins, my priests have forgotten me. Will you rebuild my shrine, mortal? Restore it in all its glory? Accomplish this, and I will reward you. You will be the bearer of Goldbrand, my sword of legend. There is one who can help you do this for me. Listen....",
    ["sound/vo/misc/da_boethiahintro2.wav"]="Rough hands to smooth stone, Carving rock instead of bone, In Caldera an artist waits, His masterpiece to create. Find the one who may shape the rock. Go.",
    ["sound/vo/misc/da_malacathcomplete.wav"]="You have killed the false hero, and ensured there will be no more to follow. You have helped bring honor back to the Orcish people, and for that I am glad. Here, take the Helm of Oreyn Bearclaw. Wear it proudly, and let it serve as a reminder of what really happened.",
    ["sound/vo/misc/da_malacathintro1.wav"]="You have summoned me, orc? Have you come to restore the honor of your people? I have in my possession the Helm of Oreyn Bearclaw, the dark elven 'hero.' His deeds are numerous, but he was a false hero. They were performed by Kharag gro-Khar, his orcish friend. It is time this legend of this hero was put to rest. Find the last of his bloodline, kill him, and I will grant you the Helm. Look for him in the city where the Man-God lives.",
    ["sound/vo/misc/da_malacathintro2.wav"]="You have summoned me? Hmmph. You are all the same. But, perhaps you can be of use to me. I have in my possession the Helm of Oreyn Bearclaw, the dark elven 'hero.' His deeds are numerous, but he was a false hero. All were performed by Kharag gro-Khar, his orcish friend. It is time this legend was put to rest. Find the last of his bloodline, kill him, and I will grant you the Helm. Look for the him in the city where the Man-God lives.",
    ["sound/vo/misc/da_mehruneschoice1.wav"]="You are brave or foolish. Perhaps both. This, then, is your chance to prove your courage. My Razor, slayer of man and mer, scourge of all who stand before it, lies dormant. Stolen by an unworthy bearer, an elf of little courage or consequence, it lies unused, gathering dust in the Alas Tomb near Molag Mar. Return it to me, mortal. Prove yourself to be a worthy bearer of Mehrunes' Razor.",
    ["sound/vo/misc/da_mehruneschoice2.wav"]="I expected little else. Take your leave of this place or die where you stand.",
    ["sound/vo/misc/da_mehrunescomplete.wav"]="You've found my Razor. Good. Can you feel its hunger? Can you feel its frustration? Now, I will make it again what it once was, what it shall always be. Draw a line of blood across the land in the name of Mehrunes Dagon!",
    ["sound/vo/misc/da_mehrunesintro.wav"]="Why do you call on me, little mortal? Do you seek your death so soon? I should crush you where you stand, yet you show mettle by even approaching me. How ambitious are you, little one.",
    ["sound/vo/misc/da_mephalacomplete.wav"]="You have done well, mortal. There are some things that must be done to preserve the order. And it will be amusing for me when this business comes to light. I look forward to it. Take this ring, mortal. Through the brightest day it will carry you with speed and stealth. Leave me now.",
    ["sound/vo/misc/da_molagbalcomplete.wav"]="Ah, you have freed the soul of Menta Na! Torment will be his. Endless agony is all he will know until the end of time. You have performed well, mortal. Perhaps you will be my servant again one day. Take this and use it well. Bring strife and discord with you wherever you may travel. Now go.",
    ["sound/vo/misc/da_molagbalintro1.wav"]="Why do you summon me now? I have no time for your pleadings, weakling. I have other matters that need my attention. Menta Na!!! He will pay for his insolence. Listen well--those in my service will do my bidding, or they will suffer eternal torment. You will serve me, mortal.",
    ["sound/vo/misc/da_molagbalintro2.wav"]="Menta Na has grown careless and lazy. He sits in his wretched cave while life on the surface goes on unmolested. He was spawned a creature of terror! His role is to sow fear and discord among men and mer, yet he is content to stay locked in his cave and mock my will!",
    ["sound/vo/misc/da_molagbalintro3.wav"]="Kill him, mortal. Set his soul flying to the Outer Realms so that I might show him eternal torture for his disobedience. Take this key. You will find him in in the caves of Kora-Dur, east of Kogoruhn. Kill this lazy fool for me, mortal. Do this, and you will have my favor.",
    ["sound/vo/misc/da_sheogorathcomplete.wav"]="Ah...I see you have completed my little errand. Well done. Perhaps you've gotten a taste of madness as well? Do not believe madness to be a curse, mortal. For some, it is the greatest of blessings...a bitter mercy perhaps, but mercy nonetheless. Give me the Fork of Horripilation. I believe I have something more suitable for your needs. Go now. Remember what you have seen.",
    ["sound/vo/misc/da_sheogorathintro.wav"]="What is it, mortal? Have you come to be of service to Sheogorath? That in and of itself speaks toward your madness. This pleases me. Fetch the Fork of Horripilation from the mad hermit near Ald Redaynia. Take care with him. He's not the most...stable man.",
    ["sound/vo/misc/da_sheogorathintro2.wav"]="Use the Fork wisely, mortal. Few have wielded it who have not come away changed. Use the Fork to strike a deathblow to the giant bull netch that resides near the hermit. Do this, return the Fork of Horripilation to me, and Sheogorath will reward you well.",
    ["sound/vo/misc/dagoth ur taunt 1.mp3"]="Come, Nerevar. Friend or traitor, come. Come and look upon the Heart, and Akulakhan. And bring Wraithguard... I have need of it.",
    ["sound/vo/misc/dagoth ur taunt 2.mp3"]="Come to the Heart Chamber. I wait for you there, where we last met, countless ages ago.",
    ["sound/vo/misc/dagoth ur taunt 3.mp3"]="Come to me, through fire and war. I welcome you.",
    ["sound/vo/misc/dagoth ur taunt 4.mp3"]="Welcome, Moon-and-Star. I have prepared a place for you.",
    ["sound/vo/misc/dagoth ur taunt 5.mp3"]="Come. Bring Wraithguard to the Heart Chamber. Together let us free the cursed false gods.",
    ["sound/vo/misc/dagoth ur taunt 6.mp3"]="Welcome, Nerevar. Together we shall speak for the Law and the Land, and shall drive the mongrel dogs of the Empire from Morrowind.",
    ["sound/vo/misc/dagoth ur taunt 7.mp3"]="Is this how you honor the Sixth House, and the tribe unmourned? Come to me openly, and not by stealth.",
    ["sound/vo/misc/dagoth ur welcome a.wav"]="Dagoth Ur welcomes you, Nerevar, my old friend. But to this place where destiny is made, why have you come unprepared?",
    ["sound/vo/misc/dagoth ur welcome b.wav"]="Welcome, Moon-and-Star, to this place where destiny is made.",
    ["sound/vo/misc/dagoth ur welcome c.wav"]="What a fool you are. I'm a god. How can you kill a god? What a grand and intoxicating innocence. How could you be so naive? There is no escape. No Recall or Intervention can work in this place. Come. Lay down your weapons. It is not too late for my mercy.",
    ["sound/vo/misc/duelbegin.wav"]="Let the duel begin!",
    ["sound/vo/misc/helsass1.wav"]="...supposed to be here somewhere...",
    ["sound/vo/misc/helsass2.wav"]="...he told us in the Queen Mother's chambers...",
    ["sound/vo/misc/helsass3.wav"]="...behind the screen...",
    ["sound/vo/misc/hit heart 1.wav"]="What are you doing?",
    ["sound/vo/misc/hit heart 2.wav"]="WHAT ARE YOU DOING?!",
    ["sound/vo/misc/hit heart 3.wav"]="FOOL!",
    ["sound/vo/misc/hit heart 4.wav"]="STOP!",
    ["sound/vo/misc/hit heart 6.wav"]="This is the end. The bitter, bitter end.",
    ["sound/vo/misc/ms_performers1.mp3"]="Good evening to you, serjo.",
    ["sound/vo/misc/ms_performers2.mp3"]="No, serjo, it's only me here. My master, Sedura Kena Telvanni Hordalf Xyr, is at his winter estate. Is there something I can do for you?",
    ["sound/vo/misc/ms_performers3.mp3"]="Not at all, serjo. Please. May I offer you some flin?",
    ["sound/vo/misc/ms_performers4.mp3"]="Anara, serjo.",
    ["sound/vo/misc/ms_performers5.mp3"]="More than a fortnight ago. That's why it's only me in the castle, serjo. All the other servants and slaves who tend to his lordship travel with him. Is there something wrong?",
    ["sound/vo/misc/ms_performers6.mp3"]="No, serjo. I know no one by that name.",
    ["sound/vo/misc/ms_performers7.mp3"]="B'vek, that's strange. I suppose it's possible that my master knew this man, but being an Ashlander and my master being of the House of Telvanni, well, if you'll pardon me for being flippant, serjo, I don't think they would be friends.",
    ["sound/vo/misc/ms_performers8.mp3"]="Please, serjo, go wherever you want. We have nothing to hide. We're loyal Imperial subjects.",
    ["sound/vo/misc/ms_vampiremolag1.wav"]="So, you do not enjoy the blood hunger, little leech? Do you miss the warmth of the sun? I can obtain the cure for you, but you will help me first. You will find my daughter, Molag Grunda, in the dungeon Dubdilla below Mt. Assarnibibi. There she hides with her consort, the lowly atronach Nomeg Gwai. She believes hiding in a sorcerer's cave will shield her from my eyes. Foolish girl!",
    ["sound/vo/misc/ms_vampiremolag2.wav"]="I ordered her not to associate with these animals. I told her what the penalty would be for her disobediance! Yet she continues to defy me! Willful beast! I cannot have this. Find her, mortal. Kill her and the atronach, so I may deal with them in the Outer Realms. When this is done, return to me, and I will rid you of your unlife. Take care, mortal, for she is powerful. She is still a daughter of Molag Bal.",
    ["sound/vo/misc/ms_vampiremolag3.wav"]="I see you have done as I asked, little vampire. It was not easy for me to obtain the cure, but I was able to pry it from Vaermina after some...discussion. You have earned it. Now I have eternity to punish my daughter for her defiance. Your curse is lifted. Yet...I wonder, will you miss the taste of blood on your lips? When you sleep, will you taste the salt and copper flowing over your tongue? Go, mortal. Bask in your precious sunlight.",
    ["sound/vo/misc/tr_almaend_1.mp3"]="Nerevarine. Here it ends. This Clockwork City was to be your death. You were to be my greatest martyr! The heroic Nerevarine, sacrificing all to protect Morrowind from the mad Sotha Sil. But you live! You live!",
    ["sound/vo/misc/tr_almaend_2.mp3"]="Fear not. I will tell the tale myself when this is done. I will tell my people how with your dying breath you proclaimed your devotion to me, the one true god. Your death will end this prophecy and unite my people again under one god, one faith, one rule by my divine law. The puppet king will lay down his arms and bow to my will. Those who do not yield will be destroyed.",
    ["sound/vo/misc/tr_almaend_3.mp3"]="The Mazed Band has allowed me to travel to this place. Here, I slew Sotha Sil. Here, I summoned the Fabricants to attack Mournhold. I will be the savior of my people! I alone will be their salvation!",
    ["sound/vo/misc/tr_almaend_4a.mp3"]="But I smell the blood of gods on your hands, Nerevarine. Vivec was a fool. I'm sorry I wasn't there to see his death. But Sotha Sil...he always thought himself our better, shunning us, locking himself in this hole. He spoke not a word as he died. Not a whisper. Even in death, he mocked me with his silence! But I think you will scream, mortal. For now, you face the one true god.",
    ["sound/vo/misc/tr_almaend_4b.mp3"]="None may stand in my way. Not you, and certainly not Vivec. He is a poet, a fool. I will deal with him when I have finished with you. And Sotha Sil...he always thought himself our better, shunning us, locking himself in this hole. He spoke not a word as he died. Not a whisper. Even in death, he mocked me with his silence! But I think you will scream, mortal. For now, you face the one true god",
    ["sound/vo/misc/tr_almgreet1.mp3"]="Many Blessings upon you, my loyal servant.",
    ["sound/vo/misc/tr_almgreet2.mp3"]="Come. Bathe in the light of My Mercy.",
    ["sound/vo/misc/tr_almgreet3.mp3"]="What may I do for you, my child?",
    ["sound/vo/misc/tr_azuraend1.mp3"]="You have done well, mortal. The death of Almalexia is a boon for all of Morrowind, though it may take time for this to be understood. She would have betrayed the Dunmer as surely as she betrayed all those she loved. This was her curse, and this was her undoing.",
    ["sound/vo/misc/tr_azuraend2.mp3"]="Weep not for Sotha Sil. He shed his mortality long ago, and I am certain his death was no small relief to him. These gods lived with the burden of a power no mortal was meant to possess.",
    ["sound/vo/misc/tr_azuraend3a.mp3"]="There is much for you still to do. Vivec lives, and he may yet have a part to play in your future. Continue on your chosen path. The skies of Mournhold are clear once again. Let these people suffer no longer. Now go, mortal. Embrace your destiny, and go with my blessing.",
    ["sound/vo/misc/tr_azuraend3b.mp3"]="There is much for you still to do. Vivec, is dead, though I thought he might play a part in your future. Continue on your chosen path. The skies of Mournhold are clear once again. Let these people suffer no longer. Now go, mortal.Embrace your destiny, and go with my blessing.",
    ["sound/vo/misc/tr_azuraend3c.mp3"]="Your work in Morrowind is not finished, Nerevarine. Vivec still lives, but I believe his time grows short. Protect my people. Defend these lands. The skies of Mournhold are clear once again. Let these people suffer no longer. Now go, mortal. Embrace your destiny, and go with my blessing.",
    ["sound/vo/misc/tr_azuraend3d.mp3"]="Your work in Morrowind is not finished, Nerevarine. The Tribunal are dead, and the faith of my people is shaken. Protect them. Defend these lands. The skies of Mournhold are clear once again. Let these people suffer no longer. Now go, mortal. Embrace your destiny, and go with my blessing.",
    ["sound/vo/misc/tr_highord_4.mp3"]="Take arms! Drive back these creatures!!!",
    ["sound/vo/misc/tr_royal_4.mp3"]="Attack the creatures!! We must defend the city!!!!",
    ["sound/vo/misc/wolfdoor.mp3"]="A booming voice calls out.",
    ["sound/vo/misc/wolfdoorfalse.mp3"]="You answered incorrectly.",
    ["sound/vo/misc/wolfdoornone.mp3"]="You did not answer.",
    ["sound/vo/misc/wolfdoortrue.mp3"]="You answered correctly.",
    ["sound/vo/n/m/flw_nm001.mp3"]="Do you know where you're going?",
    ["sound/vo/o/f/flw_of003.mp3"]="Thank you.",
    ["sound/vo/o/f/flw_of004.mp3"]="Hey! Wait for me!",
    ["sound/vo/r/f/flw_rf003.mp3"]="Thank you.",
    ["sound/vo/r/f/flw_rf004.mp3"]="Wait for me!",
    ["sound/vo/r/f/flw_rf006.mp3"]="Thank you.",
    ["sound/vo/w/m/fle_wm005.mp3"]="WAAAAAAAOOOOOOOOOOAAAAAAAAAGGGHHHHHH!!!!!",
    ["sound/vo/w/m/hit_wm006.mp3"]="AAAAAAARRRRRRGGGGGGGGGGGGGGGGGGGG!!!!!!",
  },
  automatic={
    ["sound/vo/a/f/flw_af001.mp3"]="Is this the way? Where are you going?",
    ["sound/vo/a/f/flw_af003.mp3"]="Thank you. You have our blessings, Sirah.",
    ["sound/vo/a/f/flw_af004.mp3"]="Wait for me!",
    ["sound/vo/a/f/flw_af006.mp3"]="Three blessings to you. You have our thanks.",
    ["sound/vo/a/f/op_af001.mp3"]="Grab her!",
    ["sound/vo/a/f/op_af002.mp3"]="Grab him!",
    ["sound/vo/a/f/op_af003.mp3"]="She's over here!",
