    ["sound/vo/a/f/srv_af012.mp3"]="Leave before I eat it.",
    ["sound/vo/a/m/batk_am001.mp3"]="Kill the beast.",
    ["sound/vo/a/m/batk_am002.mp3"]="Your head will be my new trophy.",
    ["sound/vo/a/m/batk_am005.mp3"]="Your cursed bloodline ends here.",
    ["sound/vo/a/m/batk_am006.mp3"]="I've got the cure for your curse right here.",
