    ["sound/vo/d/f/flw_df001.mp3"]="Are you sure you know the way?",
    ["sound/vo/d/f/flw_df006.mp3"]="How can I show my appreciation? Ah, yes, thank you!",
    ["sound/vo/d/f/op_df003.mp3"]="She's over here!",
    ["sound/vo/d/f/op_df004.mp3"]="He's over here!",
    ["sound/vo/d/f/op_df005.mp3"]="There he is!",
