    ["sound/vo/d/f/op_df007.mp3"]="Seize her!",
    ["sound/vo/d/f/op_df008.mp3"]="Seize him!",
    ["sound/vo/d/f/srv_df001.mp3"]="I would be honored to trade wares with you.",
    ["sound/vo/d/f/srv_df002.mp3"]="at your service outrander.",
    ["sound/vo/d/f/srv_df003.mp3"]="You disgust me. Please leave.",
    ["sound/vo/d/f/srv_df004.mp3"]="I have heard of you, Outlander. Feel free to peruse my goods.",
    ["sound/vo/d/f/srv_df005.mp3"]="the freshest ingredients in town.",
    ["sound/vo/d/f/srv_df006.mp3"]="If you don't leave now, I shall call the gods.",
